$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$ExpectedHead = '63af23e'
$RepoRoot = (Get-Location).Path
$GitRoot = (git rev-parse --show-toplevel 2>$null)
if ($LASTEXITCODE -ne 0) { throw "Current directory is not inside a Git repository." }
$NormalizePath = { param([string]$Path) ([System.IO.Path]::GetFullPath($Path).TrimEnd('\', '/')) }
if ((& $NormalizePath $GitRoot) -ine (& $NormalizePath $RepoRoot)) {
    throw "Run from the LYAPUNOV repository root. Git root: $GitRoot"
}
if ((git branch --show-current) -ne 'main') { throw "Expected branch main." }
$Head = (git rev-parse --short HEAD).Trim()
if ($Head -ne $ExpectedHead) { throw "Expected HEAD $ExpectedHead but found $Head. Reconcile first." }
git diff --quiet
if ($LASTEXITCODE -ne 0) { throw "Tracked working-tree changes exist. Stop and review." }
git diff --cached --quiet
if ($LASTEXITCODE -ne 0) { throw "Staged changes exist. Stop and review." }
$Payload = [System.Collections.Generic.Dictionary[string,string]]::new()
$Payload.Add('src/main/java/com/lyapunov/inbox/InboxKey.java', '')
$Payload.Add('src/main/java/com/lyapunov/inbox/InboxWork.java', '')
$Payload.Add('src/main/java/com/lyapunov/inbox/InboxProcessingResult.java', 'cGFja2FnZSBjb20ubHlhcHVub3YuaW5ib3g7CgovKiogUmVzdWx0IG9mIGF0dGVtcHRpbmcgdG8gcHJvY2VzcyBvbmUgZXZlbnQuICovCnB1YmxpYyBlbnVtIEluYm94UHJvY2Vzc2luZ1Jlc3VsdCB7IFBST0NFU1NFRCwgRFVQTElDQVRFIH0K')
$Payload.Add('src/main/java/com/lyapunov/inbox/JdbcInboxProcessor.java', '')
$Payload.Add('src/main/resources/db/migration/V007__consumer_inbox.sql', '')
$Payload.Add('src/test/java/com/lyapunov/inbox/InboxKeyTest.java', '')
$Payload.Add('docs/CONSUMER_INBOX_IDEMPOTENCY.md', '')
foreach ($Entry in $Payload.GetEnumerator()) {
  $Destination = Join-Path $RepoRoot $Entry.Key
  $Directory = Split-Path -Parent $Destination
  if (-not (Test-Path $Directory)) { New-Item -ItemType Directory -Path $Directory -Force | Out-Null }
  [System.IO.File]::WriteAllBytes($Destination, [Convert]::FromBase64String($Entry.Value))
  Write-Host "Created $($Entry.Key)"
}
Write-Host "`nRunning Maven verification..."
& .\mvnw.cmd -B -ntp clean verify
if ($LASTEXITCODE -ne 0) { throw "Maven verification failed. Nothing was staged or committed." }
$Paths = @(
    'src/main/java/com/lyapunov/inbox/InboxKey.java',
    'src/main/java/com/lyapunov/inbox/InboxWork.java',
    'src/main/java/com/lyapunov/inbox/InboxProcessingResult.java',
    'src/main/java/com/lyapunov/inbox/JdbcInboxProcessor.java',
    'src/main/resources/db/migration/V007__consumer_inbox.sql',
    'src/test/java/com/lyapunov/inbox/InboxKeyTest.java',
    'docs/CONSUMER_INBOX_IDEMPOTENCY.md'
)
git add -- $Paths
if ($LASTEXITCODE -ne 0) { throw "git add failed." }
git diff --cached --check
if ($LASTEXITCODE -ne 0) { throw "Staged whitespace validation failed." }
git commit -m "feat: add transactional consumer inbox idempotency"
if ($LASTEXITCODE -ne 0) { throw "Commit failed." }
git push origin main
if ($LASTEXITCODE -ne 0) { throw "Push failed. Local commit is retained." }
Write-Host "`nBATCH 10 COMPLETE: verified, committed, and pushed."
git log -1 --oneline
git status -sb
